const body = $('Webhook').item.json.body || {};
const ex = JSON.parse($('OpenAI: Extract Idea').item.json.message.content);
return [{ json: {
  idea: ex.idea || body.raw_text.slice(0, 280),
  thesis: ex.thesis || null,
  distribution: Array.isArray(ex.distribution) ? ex.distribution : null,
  confidence: typeof ex.confidence === 'number' ? ex.confidence : null,
  source_type: body.source_type || 'manual',
  source_ref: body.source_ref || null,
  source_url: body.source_url || null,
  source_snippet: body.source_snippet || body.raw_text.slice(0, 280),
  source_captured_at: body.captured_at || new Date().toISOString(),
  state: 'seeded',
  assigned_to: 'cleo',
} }];
